 public sealed class KindLabelConverter:IValueConverter {public object Convert(object value,Type targetType,object parameter,CultureInfo culture){string kind=System.Convert.ToString(value);return kind=="Seestar SMB"?"Seestar":kind=="DWARF FTP"?"DWARF":"Local folder";}public object ConvertBack(object value,Type targetType,object parameter,CultureInfo culture){throw new NotSupportedException();}}
 public class ProbeResult {public bool Success;public string Error;public int ErrorCode;public List<Entry> Entries;}
