 public static class Program {
  [STAThread] public static int Main(string[] args){
   if(args.Length>=3&&args[0]=="--worker")return Worker(args[1],args[2]);
   try{return RunUi(args);}catch(Exception e){if(args.Length>0&&args[0].StartsWith("--ui-",StringComparison.Ordinal))StartupDiagnostics.Save(e);else ShowError(e);return 1;}
  }
  // Keep WPF loading inside the catch boundary so missing framework assemblies
  // can be reported through the independent Windows Forms fallback.
  [MethodImpl(MethodImplOptions.NoInlining)] static int RunUi(string[] args){
   var app=new Application();RemoteUi ui=null;
   app.DispatcherUnhandledException+=(s,e)=>{if(args.Length>0&&args[0].StartsWith("--ui-",StringComparison.Ordinal)){StartupDiagnostics.Save(e.Exception);Environment.Exit(1);}else{ShowError(e.Exception);e.Handled=true;}};
   ui=new RemoteUi();
   if(args.Length==2&&args[0]=="--ui-test"){
    string output=Path.GetFullPath(args[1]);Directory.CreateDirectory(output);
    ui.CheckDiscoverySelection();ui.CheckStartGate();ui.Window.Show();ui.Window.UpdateLayout();
    var frame=new DispatcherFrame();ui.Window.Dispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);
    foreach(string theme in new[]{"Light","Dark"})foreach(int page in new[]{0,1,2}){Theme.Apply(ui.Window,theme);ui.PreparePreview(page);ui.Window.UpdateLayout();var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap((int)ui.Window.ActualWidth,(int)ui.Window.ActualHeight,96,96,System.Windows.Media.PixelFormats.Pbgra32);bitmap.Render(ui.Window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var f=File.Create(Path.Combine(output,"Remote-"+theme+"-"+page+".png")))encoder.Save(f);}
    File.WriteAllText(Path.Combine(output,"ui-startup-passed.txt"),"Native WPF window, source-change guard and three pages passed; rendered in Light and Dark themes.");ui.Window.Close();return 0;
   }
   if(args.Length==2&&args[0]=="--ui-demo-test"){
    string output=Path.GetFullPath(args[1]);Directory.CreateDirectory(output);ui.Window.Show();
    SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(ui.Window.Dispatcher));
    var task=ui.CheckDemo();var frame=new DispatcherFrame();task.ContinueWith(t=>ui.Window.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();
    File.WriteAllText(Path.Combine(output,"ui-demo-passed.txt"),"One-click demo copied original bytes through the EXE worker, stopped safely and verified its saved files.");ui.Window.Close();return 0;
   }
   app.Run(ui.Window);return 0;
  }
  [MethodImpl(MethodImplOptions.NoInlining)] static void ShowError(Exception error){
   string path=StartupDiagnostics.Save(error),details=StartupDiagnostics.Details(error);
   try{using(var dialog=new System.Windows.Forms.Form{Text="Remote tester could not continue",Width=820,Height=550,StartPosition=System.Windows.Forms.FormStartPosition.CenterScreen}){
    var message=new System.Windows.Forms.Label{Text="The error has been saved. Use Copy details to share it.\r\n"+(path??"No writable log location was available."),Dock=System.Windows.Forms.DockStyle.Top,Height=62,Padding=new System.Windows.Forms.Padding(12)};
    var text=new System.Windows.Forms.TextBox{Text=details,Multiline=true,ReadOnly=true,ScrollBars=System.Windows.Forms.ScrollBars.Both,Dock=System.Windows.Forms.DockStyle.Fill,WordWrap=false};
    var buttons=new System.Windows.Forms.FlowLayoutPanel{Dock=System.Windows.Forms.DockStyle.Bottom,Height=48,Padding=new System.Windows.Forms.Padding(8)};
    var copy=new System.Windows.Forms.Button{Text="Copy details",Width=120};copy.Click+=(s,e)=>{try{System.Windows.Forms.Clipboard.SetText(details);}catch{}};buttons.Controls.Add(copy);
    var close=new System.Windows.Forms.Button{Text="Close",Width=90};close.Click+=(s,e)=>dialog.Close();buttons.Controls.Add(close);dialog.Controls.Add(text);dialog.Controls.Add(message);dialog.Controls.Add(buttons);dialog.ShowDialog();
   }}catch{try{System.Windows.Forms.MessageBox.Show(details,"Remote tester startup error");}catch{}}
  }
  static int Worker(string configPath,string work){try{Connection c=Json.Read<Connection>(configPath);string mode=File.ReadAllText(Path.Combine(work,"mode"));c.Validate(mode!="list");using(var source=Downloader.Source(c)){if(mode=="list"){Json.Save(Path.Combine(work,"result.json"),new ProbeResult{Success=true,Entries=source.List(c.Folder)});return 0;}
   Action<Notice> report=n=>File.AppendAllText(Path.Combine(work,"events.jsonl"),Json.Serialize(n)+Environment.NewLine,new UTF8Encoding(false));var downloader=new Downloader(c,source,report);if(mode=="verify"){downloader.Verify();return 0;}
   // OS releases the lock if the worker is stopped or crashes.
   string lockFile=Paths.Local(c.Destination,".remote-tester/download.lock");using(var guard=new FileStream(lockFile,FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){int failures=0;while(true){try{downloader.Poll();failures=0;}catch(Exception e){failures++;report(new Notice{State="Connection",Message="File access unavailable; retrying: "+e.Message});}Thread.Sleep(TimeSpan.FromSeconds(failures==0?c.PollSeconds:Math.Min(30,5*failures)));}}
  }}catch(Exception e){try{Json.Save(Path.Combine(work,"result.json"),new ProbeResult{Success=false,Error=e.Message,ErrorCode=e.HResult});}catch{}return 1;}}
  public static void WriteSample(string path,int seed,bool slow){string[] cards={Card("SIMPLE","T"),Card("BITPIX","16"),Card("NAXIS","2"),Card("NAXIS1","16"),Card("NAXIS2","16"),"END".PadRight(80)};byte[] header=Encoding.ASCII.GetBytes(string.Join("",cards).PadRight(2880)),pixels=new byte[2880];for(int i=0;i<256;i++){short value=(short)(seed*100+i);pixels[i*2]=(byte)(value>>8);pixels[i*2+1]=(byte)value;}Directory.CreateDirectory(Path.GetDirectoryName(path));using(var f=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.ReadWrite)){f.Write(header,0,header.Length);f.Flush();if(slow)Thread.Sleep(1200);f.Write(pixels,0,512);f.Flush();if(slow)Thread.Sleep(1200);f.Write(pixels,512,pixels.Length-512);f.Flush(true);}}
  static string Card(string key,string value){return (key.PadRight(8)+"= "+value.PadLeft(20)).PadRight(80);}
 }
