  string Kind{get{return Convert.ToString(Combo("KindBox").SelectedItem);}}
  void Navigate(int selected){page=selected;string[] pages={"ConnectionPage","DownloadsPage","HelpPage"},buttons={"NavConnection","NavDownloads","NavHelp"};for(int i=0;i<pages.Length;i++){Find<ScrollViewer>(pages[i]).Visibility=i==selected?Visibility.Visible:Visibility.Collapsed;Button(buttons[i]).SetResourceReference(Control.BackgroundProperty,i==selected?"Selection":"Surface");Button(buttons[i]).FontWeight=i==selected?FontWeights.SemiBold:FontWeights.Normal;}Label("PageTitle").Text=selected==0?"Connect your telescope":selected==1?"Your downloads":"Help & diagnostics";Label("PageSubtitle").Text=selected==0?"Find it on your network, then choose which exposures to download.":selected==1?"Completed exposures arrive here while you keep shooting.":"Set up your connection and get useful details when something fails.";}
  string Fingerprint(Connection c){return Downloader.HashText(Json.Serialize(new{c.Kind,c.Host,c.Folder,c.Port,c.User,c.Password,c.SmbMode}));}
  void InvalidateConnection(){connectedSource=null;if(!busy)Label("ConnectionBadge").Text="Not connected";Label("FolderStatus").Text="Connect to see the folders available on your telescope.";UpdateStart();}
  void UpdateStart(){Button("StartButton").IsEnabled=!busy&&connectedSource!=null;}
  void ClearFeedback(){Find<Border>("FeedbackPanel").Visibility=Visibility.Collapsed;}
