  string ConnectionHint(string error){if(Kind=="Local simulator")return "Choose a local source folder that exists and a separate download destination. You can also use Try a local demo to create both automatically.";if(error.Contains("STATUS_BAD_NETWORK_NAME"))return "The telescope did not expose that storage share. Check the share name in its current instructions, then retry.";if(error.Contains("STATUS_OBJECT_NAME_NOT_FOUND")||error.Contains("STATUS_OBJECT_PATH_NOT_FOUND")||error.Contains("STATUS_NOT_A_DIRECTORY"))return "The telescope replied, but this folder was not found. Try Storage root, then open the folders for your capture session.";if(Kind=="Seestar SMB"&&(error.IndexOf("password",StringComparison.OrdinalIgnoreCase)>=0||error.Contains("STATUS_LOGON_FAILURE")||error.Contains("STATUS_ACCESS_DENIED")))return Combo("SmbModeBox").SelectedIndex==1?"Windows rejected file access. Choose Direct telescope access above and retry; it does not need Windows SMB policy changes.":"The telescope rejected guest access. Confirm its firmware provides a guest file share and check Seestar's instructions. The Wi-Fi password is separate from file-share authentication.";if(error.IndexOf("SMBLibrary",StringComparison.OrdinalIgnoreCase)>=0)return "Extract the entire downloaded ZIP into one folder and run the EXE there. Its companion SMBLibrary.dll is required for direct access.";return "Confirm the telescope address and that this PC shares its network. Reconnect Wi-Fi if needed, refresh discovery, then try Connect & browse again. Technical details are available below.";}
  void UpdateMetrics(){int downloaded=rows.Count(r=>r.State=="Downloaded"||r.State=="Verified"),waiting=rows.Count(r=>r.State=="Waiting"||r.State=="Downloading"),attention=rows.Count(r=>r.State=="Retry"||r.State=="Failed");Label("DownloadedCount").Text=downloaded.ToString();Label("WaitingCount").Text=waiting.ToString();Label("AttentionCount").Text=attention.ToString();Label("SummaryText").Text=rows.Count+" exposure(s)";Label("DownloadsEmpty").Visibility=rows.Count==0?Visibility.Visible:Visibility.Collapsed;}
  public void PreparePreview(int selected){Navigate(selected);if(page!=selected)throw new InvalidOperationException("Page navigation failed.");if(selected==0){Find<DataGrid>("DiscoveryGrid").ItemsSource=new[]{new DiscoveredTelescope{Name="Seestar S50 · preview",Kind="Seestar SMB",Host="192.168.1.42"},new DiscoveredTelescope{Name="DWARF 3 · preview",Kind="DWARF FTP",Host="192.168.1.43"}};Find<DataGrid>("FolderGrid").ItemsSource=new[]{new FolderRow{Name="M31",Type="Folder",Directory=true},new FolderRow{Name="M42",Type="Folder",Directory=true}};}if(selected==1){rows.Clear();rows.Add(new FileRow{File=@"M31\raw_0001.fits",State="Downloaded",Size="5.76 MB",Message="Original bytes saved; FITS structure checked."});rows.Add(new FileRow{File=@"M31\raw_0002.fits",State="Waiting",Size="5.76 MB",Message="Waiting for the exposure to finish writing."});UpdateMetrics();}}
  public void CheckStartGate(){SetBusy(true,false);if(!Button("StopButton").IsEnabled||System.Convert.ToString(Button("StopButton").Content)!="Cancel")throw new InvalidOperationException("A pending connection cannot be cancelled.");SetBusy(false,false);var original=Read();connectedSource=Fingerprint(original);UpdateStart();if(!Button("StartButton").IsEnabled)throw new InvalidOperationException("A connected source cannot start downloads.");Box("HostBox").Text="192.168.1.99";if(Button("StartButton").IsEnabled)throw new InvalidOperationException("Changing the source did not invalidate its connection.");Apply(original);connectedSource=null;UpdateStart();}
  public async Task CheckDemo(){var demo=Simulate();try{var deadline=DateTime.UtcNow.AddSeconds(25);while(!rows.Any(r=>r.State=="Downloaded")){if(DateTime.UtcNow>deadline)throw new InvalidOperationException("The one-click demo did not produce a completed download. "+Box("ActivityBox").Text);if(demo.IsCompleted){await demo;if(worker==null)throw new InvalidOperationException("The demo did not start its download worker.");}await Task.Delay(200);}if(simulatorCancel!=null)simulatorCancel.Cancel();Stop();await demo;var sourceFiles=Directory.EnumerateFiles(active.Folder,"*.fits",SearchOption.AllDirectories).Select(Downloader.Hash).ToArray();var copies=Directory.EnumerateFiles(active.Destination,"*.fits",SearchOption.AllDirectories).ToArray();if(copies.Length==0||copies.Any(p=>!sourceFiles.Contains(Downloader.Hash(p))))throw new InvalidOperationException("The demo download differs from its independent original.");await Verify();if(!rows.Any(r=>r.State=="Verified")||rows.Any(r=>r.State=="Failed"))throw new InvalidOperationException("The one-click demo's local verification failed.");}finally{if(simulatorCancel!=null)simulatorCancel.Cancel();Stop();}}
  void Guide(){bool ftp=Kind=="DWARF FTP",sim=Kind=="Local simulator",hotspot=Combo("NetworkBox").SelectedIndex==0;Find<Expander>("FtpCredentials").Visibility=ftp?Visibility.Visible:Visibility.Collapsed;Box("HostBox").IsEnabled=!sim;Button("SourceBrowseButton").Visibility=sim?Visibility.Visible:Visibility.Collapsed;Button("StorageRootButton").Visibility=sim?Visibility.Collapsed:Visibility.Visible;Find<StackPanel>("SmbOptions").Visibility=Kind=="Seestar SMB"?Visibility.Visible:Visibility.Collapsed;Label("SmbAccessHint").Text=Combo("SmbModeBox").SelectedIndex==0?"Connects directly to the telescope. Windows security settings stay as they are.":"Uses Windows file sharing. Test the same folder in File Explorer first.";Button("DefaultsButton").Visibility=sim?Visibility.Collapsed:Visibility.Visible;Button("GuideButton").Visibility=sim?Visibility.Collapsed:Visibility.Visible;Combo("NetworkBox").IsEnabled=!sim;Find<StackPanel>("DiscoveryPanel").Visibility=sim?Visibility.Collapsed:Visibility.Visible;Button("DiscoverButton").IsEnabled=!busy&&Combo("DiscoveryNetworkBox").SelectedItem!=null;Button("UseDiscoveryButton").IsEnabled=!busy&&Find<DataGrid>("DiscoveryGrid").SelectedItem is DiscoveredTelescope;
   Label("SetupGuide").Text=sim?"Use a local folder as the source. The built-in simulator creates unique, slowly written FITS exposures for this tester. Choose a separate destination.":ftp?(hotspot?"Power on DWARF 3 or mini and tap Connect in the DWARFLAB app to enable its Wi-Fi. On this PC, open Wi-Fi settings and join the DWARF hotspot. Use the Wi-Fi password shown in the app; the documented DWARF 3 default is DWARF_12345678. Keep shooting in the phone app.":"In the DWARFLAB app, connect the telescope to your home Wi-Fi using STA mode. Connect this PC to the same LAN. Verify FTP access on your model and firmware; hotspot defaults do not apply on the home LAN."):(hotspot?"Power on Seestar. Connect your phone through the Seestar app, then join the Seestar hotspot from this PC. Use the Wi-Fi password shown in the app; the documented default is 12345678. Enable Save Each Frame in Seestar's capture settings.":"In Seestar settings, open Wi-Fi → STA Mode and join your home Wi-Fi. Reconnect the app, and connect this PC to the same LAN. Enable Save Each Frame so individual exposures are stored.");
