  }
  void RefreshNetworks(){try{var previous=Combo("DiscoveryNetworkBox").SelectedItem as DiscoveryNetwork;var networks=DiscoveryNetwork.Available();Combo("DiscoveryNetworkBox").ItemsSource=networks;Combo("DiscoveryNetworkBox").SelectedItem=previous==null?networks.FirstOrDefault():networks.FirstOrDefault(n=>n.Address==previous.Address)??networks.FirstOrDefault();Label("DiscoveryStatus").Text=networks.Count==0?"No active Wi-Fi or Ethernet IPv4 network. Connect this PC, then Refresh networks.":"Choose the network shared with the telescope, then Find telescopes (about 8 seconds).";Button("DiscoverButton").IsEnabled=!busy&&networks.Count>0;}catch(Exception e){Label("DiscoveryStatus").Text="Could not read network connections: "+e.Message;Button("DiscoverButton").IsEnabled=false;}}
  async Task Discover(){if(busy)return;var network=Combo("DiscoveryNetworkBox").SelectedItem as DiscoveryNetwork;if(network==null){RefreshNetworks();return;}Find<DataGrid>("DiscoveryGrid").ItemsSource=null;var cancel=new CancellationTokenSource();discoveryCancel=cancel;SetBusy(true,false);Button("CancelDiscoveryButton").Visibility=Visibility.Visible;Label("DiscoveryStatus").Text="Searching "+network.Display+"…";Label("ConnectionBadge").Text="Searching the network";SetStatus("Discovering DWARF and Seestar devices. Capture continues in the telescope app.");try{var result=await Task.Run(()=>TelescopeDiscovery.Find(network,cancel.Token));if(closing)return;Find<DataGrid>("DiscoveryGrid").ItemsSource=result.Devices.OrderBy(d=>d.Name).ThenBy(d=>d.Host).ToList();foreach(string warning in result.Warnings)Log(warning);string message=result.Devices.Count==0?"No telescope replies. Confirm the same subnet, the telescope is awake and guest/client isolation is off. Check Windows firewall permission for this app on your trusted private network, or enter the IP manually.":result.Devices.Count+" telescope(s) found. Select yours, then connect to it.";if(result.Warnings.Count>0)message+=" "+string.Join(" ",result.Warnings);Label("DiscoveryStatus").Text=message;SetStatus(result.Devices.Count==0?"Discovery finished without a telescope reply. See the network guidance above.":"Discovery complete. Select a telescope to fill in its address.");Log("Discovery on "+network.Display+": "+result.Devices.Count+" device(s). File access has not yet been tested.");}catch(OperationCanceledException){if(!closing){Label("DiscoveryStatus").Text="Search cancelled. You can search again or enter the IP manually.";SetStatus("Discovery cancelled.");}}catch(Exception e){if(!closing){Label("DiscoveryStatus").Text="Discovery failed: "+e.Message;Log("Discovery: "+e.Message);SetStatus("Discovery failed. You can still enter the telescope IP manually.");}}finally{discoveryCancel=null;cancel.Dispose();if(!closing){Button("CancelDiscoveryButton").Visibility=Visibility.Collapsed;Label("ConnectionBadge").Text=connectedSource==null?"Not connected":"Connected";SetBusy(false,false);}}}
  void SyncFolderAddress(){string host,suffix;if(Kind=="Seestar SMB"&&SmbPath.TrySplitAddress(Box("FolderBox").Text,out host,out suffix))Box("FolderBox").Text=@"\\"+Box("HostBox").Text.Trim()+suffix;}
  void SyncHostAddress(){string host,suffix;if(Kind=="Seestar SMB"&&SmbPath.TrySplitAddress(Box("FolderBox").Text,out host,out suffix))Box("HostBox").Text=host;}
  void UseDiscovered(){if(busy)return;var device=Find<DataGrid>("DiscoveryGrid").SelectedItem as DiscoveredTelescope;if(device==null)return;string oldKind=Kind,folder=Box("FolderBox").Text;Combo("KindBox").SelectedItem=device.Kind;Box("HostBox").Text=device.Host;if(device.Kind=="Seestar SMB"){string host,suffix;Box("FolderBox").Text=oldKind==device.Kind&&SmbPath.TrySplitAddress(folder,out host,out suffix)?@"\\"+device.Host+suffix:@"\\"+device.Host+@"\EMMC Images\MyWorks";}else Box("FolderBox").Text=oldKind==device.Kind&&folder.StartsWith("/")?folder:"/";Find<DataGrid>("FolderGrid").ItemsSource=null;SetStatus("Selected "+device.Name+" at "+device.Host+". Connect & browse will now check file access.");Log("Selected discovered "+device.Name+" · "+device.Host);}
  public void CheckDiscoverySelection(){
   var original=Read();var grid=Find<DataGrid>("DiscoveryGrid");var seestar=new DiscoveredTelescope{Kind="Seestar SMB",Name="S50 Pro test",Host="192.168.1.42"};var dwarf=new DiscoveredTelescope{Kind="DWARF FTP",Name="DWARF test",Host="192.168.1.43"};
   Combo("KindBox").SelectedItem="Seestar SMB";Box("FolderBox").Text=@"\\10.0.0.1\EMMC Images\MyWorks\session";grid.ItemsSource=new[]{seestar};grid.SelectedItem=seestar;UseDiscovered();UseDiscovered();if(Box("HostBox").Text!=seestar.Host||Box("FolderBox").Text!=@"\\192.168.1.42\EMMC Images\MyWorks\session")throw new InvalidOperationException("Discovery did not preserve the selected SMB folder on repeated selection.");
   Box("HostBox").Text="192.168.1.44";SyncFolderAddress();if(Box("FolderBox").Text!=@"\\192.168.1.44\EMMC Images\MyWorks\session")throw new InvalidOperationException("Address editing lost the selected SMB folder.");Box("FolderBox").Text=@"\\192.168.1.45\EMMC Images\MyWorks";SyncHostAddress();if(Box("HostBox").Text!="192.168.1.45")throw new InvalidOperationException("Folder editing did not update the telescope address.");
   foreach(string draft in new[]{"","/","x",@"\",@"\\",@"\\host",@"\\host\",@"\\\share"}){Box("FolderBox").Text=draft;string host=Box("HostBox").Text;SyncFolderAddress();SyncHostAddress();if(Box("FolderBox").Text!=draft||Box("HostBox").Text!=host)throw new InvalidOperationException("Editing an incomplete folder changed the address or path.");UseDiscovered();if(Box("FolderBox").Text!=@"\\192.168.1.42\EMMC Images\MyWorks")throw new InvalidOperationException("Discovery did not recover from an incomplete folder.");}
   grid.ItemsSource=new[]{dwarf};grid.SelectedItem=dwarf;UseDiscovered();if(Kind!=dwarf.Kind||Box("HostBox").Text!=dwarf.Host||Box("FolderBox").Text!="/")throw new InvalidOperationException("Discovery did not switch to DWARF.");grid.ItemsSource=new[]{seestar};grid.SelectedItem=seestar;UseDiscovered();if(Kind!=seestar.Kind||Box("HostBox").Text!=seestar.Host||Box("FolderBox").Text!=@"\\192.168.1.42\EMMC Images\MyWorks")throw new InvalidOperationException("Discovery did not switch from DWARF root to Seestar.");
   grid.ItemsSource=null;Apply(original);Guide();Box("ActivityBox").Clear();SetStatus("Find your telescope or enter its address, then connect to a capture folder.");
  }
  void Addresses(){var lines=new List<string>{"These are this PC's addresses. Use Find telescopes to discover the telescope."};foreach(var adapter in NetworkInterface.GetAllNetworkInterfaces().Where(a=>a.OperationalStatus==OperationalStatus.Up&&a.NetworkInterfaceType!=NetworkInterfaceType.Loopback)){var properties=adapter.GetIPProperties();foreach(var address in properties.UnicastAddresses.Where(a=>a.Address.AddressFamily==System.Net.Sockets.AddressFamily.InterNetwork))lines.Add(adapter.Name+": PC "+address.Address+" · mask "+address.IPv4Mask);foreach(var gateway in properties.GatewayAddresses)lines.Add("Gateway / router: "+gateway.Address);}lines.Add("On a home LAN, the gateway is usually your router. Its connected-device list can show the telescope IP. On a telescope hotspot, the gateway may be the telescope; confirm by testing file access.");Label("AddressesText").Text=string.Join(Environment.NewLine,lines);Label("AddressesText").Visibility=Visibility.Visible;}
  Connection Read(){int port=21,poll;if((Kind=="DWARF FTP"&&!int.TryParse(Box("PortBox").Text,out port))||!int.TryParse(Box("PollBox").Text,out poll))throw new ArgumentException("Enter whole numbers for FTP port and poll interval.");string limit=Convert.ToString(Combo("LimitBox").SelectedItem);return new Connection{Kind=Kind,Host=Box("HostBox").Text.Trim(),Folder=Box("FolderBox").Text.Trim(),Destination=Box("DestinationBox").Text.Trim(),User=Box("UserBox").Text.Trim(),Password=Find<PasswordBox>("PasswordBox").Password,Port=port,PollSeconds=poll,LimitMB=limit=="Unlimited"?0:double.Parse(limit.Split(' ')[0],CultureInfo.InvariantCulture),SmbMode=Combo("SmbModeBox").SelectedIndex==1?"Windows":"Direct",IncludeExisting=Find<CheckBox>("ExistingCheck").IsChecked==true};}
  void Apply(Connection c){Combo("SmbModeBox").SelectedIndex=c.SmbMode=="Windows"?1:0;Combo("KindBox").SelectedItem=c.Kind;Box("HostBox").Text=c.Host;Box("FolderBox").Text=c.Folder;Box("DestinationBox").Text=c.Destination;Box("UserBox").Text=c.User;Box("PortBox").Text=c.Port.ToString();Box("PollBox").Text=c.PollSeconds.ToString();Combo("LimitBox").SelectedItem=c.LimitMB==0?"Unlimited":c.LimitMB.ToString(CultureInfo.InvariantCulture)+" MB/s";Find<CheckBox>("ExistingCheck").IsChecked=c.IncludeExisting;}
  void Save(Connection c){var safe=new Connection{Kind=c.Kind,Host=c.Host,Folder=c.Folder,Destination=c.Destination,User=c.User,Port=c.Port,PollSeconds=c.PollSeconds,LimitMB=c.LimitMB,SmbMode=c.SmbMode,SmbPort=c.SmbPort,IncludeExisting=c.IncludeExisting};Json.Save(Path.Combine(state,"settings.json"),safe);}
  Process Launch(Connection c,string mode,out string path){path=Path.Combine(state,"runs",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(path);string config=Path.Combine(path,"connection.json");Json.Save(config,c);File.WriteAllText(Path.Combine(path,"mode"),mode);return Process.Start(new ProcessStartInfo{FileName=Assembly.GetExecutingAssembly().Location,Arguments="--worker \""+config+"\" \""+path+"\"",UseShellExecute=false,CreateNoWindow=true});}
  async Task Probe(){if(busy)return;Process process=null;string path=null;SetBusy(true,false);try{var c=Read();c.Validate(false);ClearFeedback();Label("ConnectionBadge").Text="Connecting…";SetStatus("Connecting and checking the capture folder…");operationCancelled=false;process=Launch(c,"list",out path);pendingOperation=process;pendingPath=path;await Task.Run(()=>{if(!process.WaitForExit(30000)){process.Kill();process.WaitForExit();throw new IOException("File access timed out. Check the network, telescope IP and selected folder.");}});if(operationCancelled){connectedSource=null;SetStatus("Connection cancelled. You can retry when ready.");return;}var result=Json.Read<ProbeResult>(Path.Combine(path,"result.json"));if(!result.Success)throw new IOException(result.Error+" (0x"+result.ErrorCode.ToString("X8")+")");Find<DataGrid>("FolderGrid").ItemsSource=result.Entries.OrderByDescending(e=>e.Directory).ThenBy(e=>e.Name).Select(e=>new FolderRow{Name=e.Name,Path=e.Path,Directory=e.Directory,Type=e.Directory?"Folder":"File"}).ToList();Save(c);connectedSource=Fingerprint(c);Label("ConnectionBadge").Text="Connected";Label("FolderStatus").Text=result.Entries.Count==0?"This folder is empty. It is ready to watch for new exposures.":result.Entries.Count+" entries. Double-click or press Enter to open a capture folder.";SetStatus("Connected. Choose a session folder or start downloads from this folder.");Log("File access succeeded: "+c.Folder+(c.Kind=="Seestar SMB"?" · "+c.SmbMode+" access":""));}catch(Exception e){connectedSource=null;if(!closing){Label("ConnectionBadge").Text="Connection failed";ShowFeedback(e is ArgumentException?"Check the connection details":"Could not open the capture folder",e is ArgumentException?e.Message:ConnectionHint(e.Message),e.ToString());SetStatus("Connection failed. Review the guidance above and retry.");Log("Connection test: "+e.Message);}}finally{pendingOperation=null;pendingPath=null;if(process!=null)process.Dispose();DeleteConfig(path);if(!closing){if(operationCancelled)Label("ConnectionBadge").Text=connectedSource==null?"Not connected":"Connected";SetBusy(false,false);}}}
  void Start(){if(busy)return;if(connectedSource==null){Navigate(0);SetStatus("Connect to a capture folder before starting downloads.");return;}try{var c=Read();if(connectedSource!=Fingerprint(c))throw new ArgumentException("The source changed. Connect to the capture folder again.");c.Validate(true);ClearFeedback();Save(c);rows.Clear();indexed.Clear();eventOffset=0;active=c;worker=Launch(c,"watch",out work);SetBusy(true,true);Navigate(1);UpdateMetrics();Label("ConnectionBadge").Text="Watching for exposures";SetStatus("Watching the capture folder. Completed exposures will download automatically.");Log("Watching "+c.Kind+" "+c.Folder+" → "+c.Destination);}catch(Exception e){ShowFeedback("Downloads could not start",e.Message,e.ToString());SetStatus("Review the download settings and retry.");}}
  void Stop(){if(pendingOperation!=null){operationCancelled=true;try{if(!pendingOperation.HasExited){pendingOperation.Kill();pendingOperation.WaitForExit(2000);}}catch(Exception e){if(!closing)Log("Cancel: "+e.Message);}DeleteConfig(pendingPath);return;}if(discoveryCancel!=null&&worker==null){discoveryCancel.Cancel();return;}if(worker!=null){try{if(!worker.HasExited){worker.Kill();worker.WaitForExit(2000);}ReadEvents();}catch(Exception e){Log("Stop: "+e.Message);}finally{worker.Dispose();worker=null;DeleteConfig(work);SetBusy(false,false);}Label("ConnectionBadge").Text="Stopped";SetStatus("Stopped. Completed files are saved. Start downloads to catch up.");}}
  async Task Verify(){if(busy)return;Process process=null;string path=null;SetBusy(true,false);try{var c=Read();c.Validate(true);process=Launch(c,"verify",out path);ClearFeedback();Label("ConnectionBadge").Text="Verifying saved files";SetStatus("Checking saved files against their download receipts…");await Task.Run(()=>{if(!process.WaitForExit(120000)){process.Kill();process.WaitForExit();throw new IOException("Verification timed out. Choose a smaller test destination.");}});if(operationCancelled){SetStatus("Verification cancelled. Saved files are unchanged.");return;}if(File.Exists(Path.Combine(path,"result.json"))){var result=Json.Read<ProbeResult>(Path.Combine(path,"result.json"));if(!result.Success)throw new IOException(result.Error);}if(File.Exists(Path.Combine(path,"events.jsonl")))foreach(string line in File.ReadAllLines(Path.Combine(path,"events.jsonl")))Consume(new JavaScriptSerializer().Deserialize<Notice>(line));Find<DataGrid>("FilesGrid").Items.Refresh();UpdateMetrics();Label("ConnectionBadge").Text="Verification finished";SetStatus("Verification finished. Review the file statuses below.");}catch(Exception e){SetStatus(e.Message);}finally{pendingOperation=null;pendingPath=null;if(process!=null)process.Dispose();DeleteConfig(path);if(!closing){if(operationCancelled)Label("ConnectionBadge").Text=connectedSource==null?"Not connected":"Connected";SetBusy(false,false);}}}
  void Tick(){if(worker==null)return;ReadEvents();if(worker.HasExited){try{string result=Path.Combine(work,"result.json");SetStatus(File.Exists(result)?Json.Read<ProbeResult>(result).Error:"Download worker stopped.");}catch{SetStatus("Download worker stopped; export the report for diagnosis.");}worker.Dispose();worker=null;DeleteConfig(work);SetBusy(false,false);}}
  void ReadEvents(){try{string path=Path.Combine(work,"events.jsonl");if(!File.Exists(path))return;using(var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)){f.Position=eventOffset;using(var reader=new StreamReader(f,Encoding.UTF8)){string tail=reader.ReadToEnd();int last=tail.LastIndexOf('\n');if(last<0)return;string complete=tail.Substring(0,last+1);eventOffset+=Encoding.UTF8.GetByteCount(complete);foreach(string line in complete.Split(new[]{'\n'},StringSplitOptions.RemoveEmptyEntries))Consume(new JavaScriptSerializer().Deserialize<Notice>(line));Find<DataGrid>("FilesGrid").Items.Refresh();UpdateMetrics();}}}catch(IOException){}catch(Exception e){Log("Report read: "+e.Message);}}
  void Consume(Notice n){if(notices.Count>=10000)notices.RemoveAt(0);notices.Add(n);if(n.State=="Connection")Label("ConnectionBadge").Text="Reconnecting…";else if(worker!=null)Label("ConnectionBadge").Text="Watching for exposures";if(!string.IsNullOrEmpty(n.File)){FileRow row;if(!indexed.TryGetValue(n.File,out row)){row=new FileRow{File=n.File};indexed[n.File]=row;rows.Add(row);}bool changed=row.State!=n.State||row.Message!=n.Message;row.State=n.State;row.Size=n.Bytes>0?(n.Bytes/1048576.0).ToString("0.00")+" MB":"";row.Message=n.Message;if(changed)Log(n.File+": "+n.State+" · "+n.Message);}else{SetStatus(n.Message);Log(n.Message);}}
  void SetBusy(bool value,bool watching){busy=value;foreach(string n in new[]{"KindBox","NetworkBox","HostBox","PortBox","UserBox","PasswordBox","SmbModeBox","FolderBox","DestinationBox","ExistingCheck","PollBox","LimitBox","TestButton","ParentButton","StorageRootButton","SourceBrowseButton","DestinationBrowseButton","DefaultsButton","StartButton","VerifyButton","SimulatorButton","DiscoverButton","RefreshNetworksButton","DiscoveryNetworkBox","DiscoveryGrid","UseDiscoveryButton"})Find<Control>(n).IsEnabled=!value;Button("StopButton").IsEnabled=value;Button("StopButton").Content=watching?"Stop":"Cancel";Find<ProgressBar>("BusyProgress").Visibility=value?Visibility.Visible:Visibility.Collapsed;if(!value){Button("StopButton").Content="Stop";Guide();Button("SimulatorButton").IsEnabled=!simulating;UpdateStart();}}
  void SetStatus(string text){Label("StatusText").Text=text;}
  void Log(string text){var box=Box("ActivityBox");if(box.Text.Length>50000)box.Text=box.Text.Substring(box.Text.Length-25000);box.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+text+Environment.NewLine);box.ScrollToEnd();}
  static void DeleteConfig(string path){try{if(path!=null)File.Delete(Path.Combine(path,"connection.json"));}catch{}}
  void Pick(string box){using(var dialog=new System.Windows.Forms.FolderBrowserDialog{Description=box=="DestinationBox"?"Choose a dedicated local download folder":"Choose the telescope network folder or local simulator source",SelectedPath=Box(box).Text,ShowNewFolderButton=box=="DestinationBox"})if(dialog.ShowDialog()==System.Windows.Forms.DialogResult.OK)Box(box).Text=dialog.SelectedPath;}
  void Open(string path){try{Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}catch(Exception e){SetStatus(e.Message);}}
  void Export(){var picker=new SaveFileDialog{Title="Save Remote tester report",FileName="AstroArchive-Remote-Test-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".json",Filter="JSON report|*.json"};if(picker.ShowDialog(Window)!=true)return;try{var c=active??Read();File.WriteAllText(picker.FileName,Json.Serialize(new{Application="AstroArchive Remote tester 0.2.1",Generated=DateTimeOffset.Now.ToString("o"),Connection=new{c.Kind,c.Host,c.Port,c.Folder,c.Destination,c.PollSeconds,c.LimitMB,c.IncludeExisting,c.SmbMode},Events=notices,Activity=Box("ActivityBox").Text,Limitations="FITS structure and local hashes only; no independent source checksums. Individual FITS exposures; no session sidecars."}),new UTF8Encoding(false));SetStatus("Report saved. It includes network addresses and file paths, but no passwords.");}catch(Exception e){SetStatus(e.Message);}}
  async Task Simulate(){if(busy||simulating)return;simulating=true;simulatorCancel=new CancellationTokenSource();var cancel=simulatorCancel;string folder=Path.Combine(state,"Simulator",DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));Combo("KindBox").SelectedItem="Local simulator";Box("FolderBox").Text=folder;Box("DestinationBox").Text=Path.Combine(state,"Demo downloads",Path.GetFileName(folder));Directory.CreateDirectory(folder);Log("Simulator source: "+folder);SetStatus("Preparing a local demo…");Button("SimulatorButton").IsEnabled=false;await Probe();if(closing){cancel.Dispose();simulatorCancel=null;simulating=false;return;}Start();try{await Task.Run(()=>{for(int i=1;i<=12;i++){cancel.Token.ThrowIfCancellationRequested();Program.WriteSample(Path.Combine(folder,"DWARF_RAW_TEST","raw_"+i.ToString("0000")+".fits"),i,true);if(cancel.Token.WaitHandle.WaitOne(1500))cancel.Token.ThrowIfCancellationRequested();}});if(!closing)Log("Simulator finished: 12 unique FITS exposures.");}catch(OperationCanceledException){}catch(Exception e){if(!closing)Log("Simulator: "+e.Message);}finally{simulating=false;cancel.Dispose();simulatorCancel=null;if(!closing)Button("SimulatorButton").IsEnabled=!busy;}}
 }
